const fs = require('fs').promises;
const path = require('path');
const { requireWithFallback } = require('../require-package');

const { buildAdminGraphqlUrl } = requireWithFallback(
  require,
  '@synclistic/shopify-client/api',
  '../../../shopify-client/api'
);

const { fetchPaginatedData, fetchMenus } = require('./export-objects');
const { importObjects: runImportObjects } = require('./import-runner');
const { createNoopLogger, createResult, getRequest } = require('./import-support');

const pagesQuery = `
  query($cursor: String) {
    pages(first: 250, after: $cursor) {
      edges {
        node {
          id
          title
          handle
          bodySummary
          body
          templateSuffix
          createdAt
          updatedAt
          publishedAt
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const productsQuery = `
  query($cursor: String) {
    products(first: 250, after: $cursor) {
      edges {
        node {
          id
          title
          handle
          createdAt
          descriptionHtml
          templateSuffix
          tags
          collections(first: 50) {
            edges {
              node {
                id
                handle
              }
            }
          }
          resourcePublicationsV2(first: 50) {
            edges {
              node {
                publication {
                  id
                  name
                }
                publishDate
              }
            }
          }
          variants(first: 250) {
            edges {
              node {
                id
                title
                price
                sku
                barcode
                inventoryItem {
                  tracked
                  unitCost {
                    amount
                    currencyCode
                  }
                }
              }
            }
          }
          images(first: 10) {
            edges {
              node {
                src
                altText
              }
            }
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const collectionsQuery = `
  query($cursor: String) {
    collections(first: 250, after: $cursor) {
      edges {
        node {
          id
          handle
          title
          descriptionHtml
          templateSuffix
          sortOrder
          image {
            url
            altText
          }
          seo {
            title
            description
          }
          ruleSet {
            appliedDisjunctively
            rules {
              column
              relation
              condition
            }
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const blogsQuery = `
  query($cursor: String) {
    blogs(first: 250, after: $cursor) {
      edges {
        node {
          id
          title
          handle
          createdAt
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const articlesQuery = `
  query($cursor: String) {
    articles(first: 250, after: $cursor) {
      edges {
        node {
          author {
            name
          }
          blog {
            id
            handle
            title
          }
          id
          title
          handle
          body
          image {
            url
            altText
          }
          publishedAt
          tags
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

async function importObjects(store, importPath, options = {}, deps = {}) {
  return runImportObjects(store, importPath, options, {
    ...deps,
    importObjectType
  });
}

async function importObjectType(store, exportData, options = {}, deps = {}) {
  const importers = {
    pages: importPages,
    products: importProducts,
    collections: importCollections,
    blogs: importBlogs,
    articles: importArticles,
    menus: importMenus,
    media: importMedia
  };

  const importer = importers[exportData.objectType];
  if (!importer) {
    throw new Error(`Import not supported for object type: ${exportData.objectType}`);
  }

  return importer(store, exportData.data, options, deps);
}

async function importPages(store, pages, options = {}, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const request = getRequest(deps);
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  const existingPages = await fetchPaginatedData(store, pagesQuery, 'pages', deps);
  const existingMap = new Map(existingPages.map((page) => [page.handle, page]));
  let created = 0;
  let updated = 0;
  let errors = 0;

  const pageCreateMutation = `
    mutation pageCreate($page: PageCreateInput!) {
      pageCreate(page: $page) {
        page { id title }
        userErrors { field message }
      }
    }
  `;

  const pageUpdateMutation = `
    mutation pageUpdate($id: ID!, $page: PageUpdateInput!) {
      pageUpdate(id: $id, page: $page) {
        page { id title }
        userErrors { field message }
      }
    }
  `;

  for (const page of pages) {
    const existing = existingMap.get(page.handle);

    try {
      if (existing) {
        if (options.createOnly) {
          continue;
        }

        logger.operation('Import', 'Updating', page.title, page.handle);
        const result = await request(
          url,
          pageUpdateMutation,
          {
            id: existing.id,
            page: {
              title: page.title,
              body: page.body,
              templateSuffix: page.templateSuffix,
              isPublished: page.publishedAt !== null
            }
          },
          headers
        );

        if (result.pageUpdate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.pageUpdate.userErrors));
        }

        updated += 1;
      } else {
        if (options.updateOnly) {
          continue;
        }

        logger.operation('Import', 'Creating', page.title, page.handle);
        const result = await request(
          url,
          pageCreateMutation,
          {
            page: {
              title: page.title,
              handle: page.handle,
              body: page.body,
              templateSuffix: page.templateSuffix,
              isPublished: page.publishedAt !== null
            }
          },
          headers
        );

        if (result.pageCreate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.pageCreate.userErrors));
        }

        created += 1;
      }
    } catch (error) {
      logger.error('Import', `Failed to import page "${page.title}": ${error.message}`);
      errors += 1;
    }
  }

  logger.success('Import', `Pages: ${created} created, ${updated} updated, ${errors} errors`);
  return createResult('pages', { created, updated, errors, filepath: options.filepath });
}

