async function importCollections(store, collections, options = {}, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const request = getRequest(deps);
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  const existingCollections = await fetchPaginatedData(store, collectionsQuery, 'collections', deps);
  const existingMap = new Map(existingCollections.map((collection) => [collection.handle, collection]));
  let created = 0;
  let updated = 0;
  let errors = 0;

  const collectionCreateMutation = `
    mutation collectionCreate($input: CollectionInput!) {
      collectionCreate(input: $input) {
        collection { id handle title }
        userErrors { field message }
      }
    }
  `;

  const collectionUpdateMutation = `
    mutation collectionUpdate($input: CollectionInput!) {
      collectionUpdate(input: $input) {
        collection { id handle title }
        userErrors { field message }
      }
    }
  `;

  for (const collection of collections) {
    const existing = existingMap.get(collection.handle);

    try {
      const input = {
        title: collection.title,
        descriptionHtml: collection.descriptionHtml,
        templateSuffix: collection.templateSuffix,
        sortOrder: collection.sortOrder,
        seo: collection.seo
          ? { title: collection.seo.title, description: collection.seo.description }
          : undefined,
        ruleSet: collection.ruleSet
          ? {
              appliedDisjunctively: collection.ruleSet.appliedDisjunctively,
              rules: collection.ruleSet.rules.map((rule) => ({
                column: rule.column,
                relation: rule.relation,
                condition: rule.condition
              }))
            }
          : undefined
      };

      if (existing) {
        if (options.createOnly) {
          continue;
        }

        logger.operation('Import', 'Updating', collection.title, collection.handle);
        const result = await request(
          url,
          collectionUpdateMutation,
          { input: { id: existing.id, ...input } },
          headers
        );

        if (result.collectionUpdate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.collectionUpdate.userErrors));
        }

        updated += 1;
      } else {
        if (options.updateOnly) {
          continue;
        }

        logger.operation('Import', 'Creating', collection.title, collection.handle);
        const result = await request(
          url,
          collectionCreateMutation,
          { input: { handle: collection.handle, ...input } },
          headers
        );

        if (result.collectionCreate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.collectionCreate.userErrors));
        }

        created += 1;
      }
    } catch (error) {
      logger.error('Import', `Failed to import collection "${collection.title}": ${error.message}`);
      errors += 1;
    }
  }

  logger.success('Import', `Collections: ${created} created, ${updated} updated, ${errors} errors`);
  return createResult('collections', { created, updated, errors, filepath: options.filepath });
}

