async function importArticles(store, articles, options = {}, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const request = getRequest(deps);
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  const existingBlogs = await fetchPaginatedData(store, blogsQuery, 'blogs', deps);
  const blogMap = new Map(existingBlogs.map((blog) => [blog.handle, blog.id]));
  const existingArticles = await fetchPaginatedData(store, articlesQuery, 'articles', deps);
  const existingMap = new Map(existingArticles.map((article) => [article.handle, article]));
  let created = 0;
  let updated = 0;
  let skipped = 0;
  let errors = 0;

  const articleCreateMutation = `
    mutation articleCreate($article: ArticleCreateInput!) {
      articleCreate(article: $article) {
        article { id title }
        userErrors { field message }
      }
    }
  `;

  const articleUpdateMutation = `
    mutation articleUpdate($id: ID!, $article: ArticleUpdateInput!) {
      articleUpdate(id: $id, article: $article) {
        article { id title }
        userErrors { field message }
      }
    }
  `;

  for (const article of articles) {
    const blogId = blogMap.get(article.blog?.handle);
    if (!blogId) {
      logger.warn('Import', `Skipping article "${article.title}": blog "${article.blog?.handle}" not found`);
      skipped += 1;
      continue;
    }

    const existing = existingMap.get(article.handle);

    try {
      const articleInput = {
        title: article.title,
        body: article.body,
        tags: article.tags,
        blogId,
        author: article.author ? { name: article.author.name } : undefined
      };

      if (article.image?.url) {
        articleInput.image = { url: article.image.url, altText: article.image.altText };
      }

      if (existing) {
        if (options.createOnly) {
          continue;
        }

        logger.operation('Import', 'Updating', article.title, article.handle);
        const result = await request(url, articleUpdateMutation, {
          id: existing.id,
          article: articleInput
        }, headers);

        if (result.articleUpdate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.articleUpdate.userErrors));
        }

        updated += 1;
      } else {
        if (options.updateOnly) {
          continue;
        }

        logger.operation('Import', 'Creating', article.title, article.handle);
        const result = await request(url, articleCreateMutation, {
          article: { ...articleInput, handle: article.handle }
        }, headers);

        if (result.articleCreate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.articleCreate.userErrors));
        }

        created += 1;
      }
    } catch (error) {
      logger.error('Import', `Failed to import article "${article.title}": ${error.message}`);
      errors += 1;
    }
  }

  logger.success(
    'Import',
    `Articles: ${created} created, ${updated} updated, ${skipped} skipped, ${errors} errors`
  );
  return createResult('articles', { created, updated, skipped, errors, filepath: options.filepath });
}

async function importMenus(store, menus, options = {}, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const request = getRequest(deps);
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  const existingMenus = await fetchMenus(store, deps);
  const existingMap = new Map(existingMenus.map((menu) => [menu.handle, menu]));
  let created = 0;
  let updated = 0;
  let errors = 0;

  const menuCreateMutation = `
    mutation menuCreate($title: String!, $handle: String!, $items: [MenuItemCreateInput!]!) {
      menuCreate(title: $title, handle: $handle, items: $items) {
        menu { id handle }
        userErrors { field message }
      }
    }
  `;

  const menuUpdateMutation = `
    mutation menuUpdate($id: ID!, $title: String!, $items: [MenuItemUpdateInput!]!) {
      menuUpdate(id: $id, title: $title, items: $items) {
        menu { id handle }
        userErrors { field message }
      }
    }
  `;

  function transformItemsForCreate(items) {
    return items.map((item) => ({
      title: item.title,
      type: item.type || 'HTTP',
      url: item.url,
      items: item.items ? transformItemsForCreate(item.items) : undefined
    }));
  }

  function transformItemsForUpdate(items, existingItems = []) {
    return items.map((item) => {
      const existing = existingItems.find((entry) => entry.title === item.title);
      return {
        id: existing?.id,
        title: item.title,
        type: item.type || 'HTTP',
        url: item.url,
        items: item.items ? transformItemsForUpdate(item.items, existing?.items || []) : undefined
      };
    });
  }

  for (const menu of menus) {
    const existing = existingMap.get(menu.handle);

    try {
      if (existing) {
        if (options.createOnly) {
          continue;
        }

        logger.operation('Import', 'Updating', menu.title, menu.handle);
        const result = await request(url, menuUpdateMutation, {
          id: existing.id,
          title: menu.title,
          items: transformItemsForUpdate(menu.items || [], existing.items || [])
        }, headers);

        if (result.menuUpdate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.menuUpdate.userErrors));
        }

        updated += 1;
      } else {
        if (options.updateOnly) {
          continue;
        }

        logger.operation('Import', 'Creating', menu.title, menu.handle);
        const result = await request(url, menuCreateMutation, {
          title: menu.title,
          handle: menu.handle,
          items: transformItemsForCreate(menu.items || [])
        }, headers);

        if (result.menuCreate.userErrors.length > 0) {
          throw new Error(JSON.stringify(result.menuCreate.userErrors));
        }

        created += 1;
      }
    } catch (error) {
      logger.error('Import', `Failed to import menu "${menu.title}": ${error.message}`);
      errors += 1;
    }
  }

  logger.success('Import', `Menus: ${created} created, ${updated} updated, ${errors} errors`);
  return createResult('menus', { created, updated, errors, filepath: options.filepath });
}

async function importMedia(store, media, options = {}, deps = {}) {
  const fsPromises = deps.fs || fs;
  const logger = deps.logger || createNoopLogger();
  const request = getRequest(deps);
  const formFactory = deps.createFormData || (() => {
    const FormData = require('form-data');
    return new FormData();
  });
  const uploadForm = deps.submitForm;
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  let created = 0;
  let errors = 0;
  let skipped = 0;

  const fileCreateMutation = `
    mutation fileCreate($files: [FileCreateInput!]!) {
      fileCreate(files: $files) {
        files { id alt }
        userErrors { field message }
      }
    }
  `;

  const stagedUploadsCreateMutation = `
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets {
          url
          resourceUrl
          parameters {
            name
            value
          }
        }
        userErrors { field message }
      }
    }
  `;

  if (options.updateOnly) {
    logger.info('Import', 'Skipping media import in update-only mode');
    return createResult('media', { created: 0, skipped: media.length, errors: 0, filepath: options.filepath });
  }

  for (const item of media) {
    try {
      if (item.localPath && options.exportDir) {
        const localFilePath = path.join(options.exportDir, item.localPath);

        try {
          await fsPromises.access(localFilePath);
          const fileContent = await fsPromises.readFile(localFilePath);
          const filename = path.basename(localFilePath);
          const ext = path.extname(filename).toLowerCase();
          const mimeTypes = {
            '.jpg': 'image/jpeg',
            '.jpeg': 'image/jpeg',
            '.png': 'image/png',
            '.gif': 'image/gif',
            '.webp': 'image/webp',
            '.svg': 'image/svg+xml',
            '.mp4': 'video/mp4',
            '.webm': 'video/webm',
            '.mov': 'video/quicktime',
            '.pdf': 'application/pdf'
          };
          const mimeType = mimeTypes[ext] || 'application/octet-stream';

          logger.operation('Import', 'Uploading', item.alt || filename, 'from local file');
          const stagedResult = await request(url, stagedUploadsCreateMutation, {
            input: [{
              filename,
              mimeType,
              resource: 'FILE',
              fileSize: fileContent.length.toString(),
              httpMethod: 'POST'
            }]
          }, headers);

          if (stagedResult.stagedUploadsCreate.userErrors.length > 0) {
            throw new Error(JSON.stringify(stagedResult.stagedUploadsCreate.userErrors));
          }

          const target = stagedResult.stagedUploadsCreate.stagedTargets[0];
          const form = formFactory();

          for (const param of target.parameters) {
            form.append(param.name, param.value);
          }
          form.append('file', fileContent, { filename, contentType: mimeType });

          if (uploadForm) {
            await uploadForm(form, target.url);
          } else {
            await new Promise((resolve, reject) => {
              form.submit(target.url, (error, response) => {
                if (error) {
                  reject(error);
                  return;
                }

                response.resume();
                response.on('end', resolve);
              });
            });
          }

          const createResultResponse = await request(url, fileCreateMutation, {
            files: [{ originalSource: target.resourceUrl, alt: item.alt || '' }]
          }, headers);

          if (createResultResponse.fileCreate.userErrors.length > 0) {
            throw new Error(JSON.stringify(createResultResponse.fileCreate.userErrors));
          }

          created += 1;
          continue;
        } catch (error) {
          if (error.code !== 'ENOENT') {
            logger.warn(
              'Import',
              `Local file upload failed for ${item.localPath}: ${error.message}, trying URL fallback`
            );
          }
        }
      }

      let originalUrl = item.originalUrl || null;
      if (!originalUrl) {
        if (item.image?.url) {
          originalUrl = item.image.url;
        } else if (item.sources?.[0]?.url) {
          originalUrl = item.sources[0].url;
        } else if (item.url) {
          originalUrl = item.url;
        }
      }

      if (!originalUrl) {
        logger.warn('Import', 'Skipping media item: no local file or URL found');
        skipped += 1;
        continue;
      }

      logger.operation('Import', 'Creating', item.alt || 'media', 'from URL');
      const result = await request(url, fileCreateMutation, {
        files: [{ originalSource: originalUrl, alt: item.alt || '' }]
      }, headers);

      if (result.fileCreate.userErrors.length > 0) {
        throw new Error(JSON.stringify(result.fileCreate.userErrors));
      }

      created += 1;
    } catch (error) {
      logger.error('Import', `Failed to import media: ${error.message}`);
      errors += 1;
    }
  }

  logger.success('Import', `Media: ${created} created, ${skipped} skipped, ${errors} errors`);
  return createResult('media', { created, skipped, errors, filepath: options.filepath });
}

